import{b as t,j as a,F as i}from"./three-92ffd73b.js";const s=[{id:"the-budget-went-to-the-hardest-problems-first",text:"The budget went to the hardest problems first",depth:2},{id:"data-quality-is-usually-the-wrong-diagnosis",text:'"Data quality" is usually the wrong diagnosis',depth:2},{id:"the-agent-did-exactly-what-it-was-told",text:"The agent did exactly what it was told",depth:2},{id:"humans-in-the-loop-wear-out",text:"Humans in the loop wear out",depth:2},{id:"what-working-looks-like",text:"What working looks like",depth:2}];function o(n){const e={a:"a",em:"em",h2:"h2",hr:"hr",p:"p",span:"span",...n.components};return a(i,{children:[t(e.p,{children:"Enterprise AI adoption numbers read like a restaurant that keeps buying ovens and never serves dinner."}),`
`,t(e.p,{children:"Spending is up everywhere, and every earnings call has its AI paragraph. Then you read the research. BCG surveyed 1,000 executives and found that only 4% of companies consistently get substantial value from AI, and only 26% have built the capabilities to get past the proof-of-concept stage at all. MIT's NANDA initiative looked at enterprise generative AI pilots and found that 95% of the organizations it studied had no measurable return to show for them."}),`
`,t(e.p,{children:"My read on why is unglamorous. The models are mostly fine. The projects that fail never answered one question precisely: what does done look like? The projects that make money tend to be the ones where the answer is so obvious nobody thought to write it down."}),`
`,a(e.h2,{id:"the-budget-went-to-the-hardest-problems-first",children:[t(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#the-budget-went-to-the-hardest-problems-first",children:t(e.span,{className:"icon icon-link"})}),"The budget went to the hardest problems first"]}),`
`,t(e.p,{children:'According to the NANDA report, more than half of corporate AI budgets go to sales and marketing tools. I understand the appeal. Revenue is measurable, and a CFO likes being able to draw a line from "AI" to "pipeline."'}),`
`,t(e.p,{children:"The returns point the other way. The report found the strongest returns in the back office: process automation, cutting outsourcing, operational plumbing. Nobody gives a keynote about invoice matching."}),`
`,t(e.p,{children:`Through the definition-of-done lens this stops being surprising. "Generate more qualified leads" is a fuzzy target in an adversarial market. Your competitors bought the same tools, buyers have grown an immune response to AI-written email, and the parts that actually close deals are still human. Invoice matching has a correct answer: the invoice matches the purchase order or it doesn't. The incumbent you're replacing is a spreadsheet and a tired person on a Thursday afternoon.`}),`
`,t(e.p,{children:"My guess is that a lot of the struggling companies started with a chatbot, because a chatbot demos well, and invoice matching has never once demoed well."}),`
`,a(e.p,{children:["(If you're trying to figure out where to start instead, ",t(e.a,{href:"/ai/",children:"this is what I do"}),".)"]}),`
`,a(e.h2,{id:"data-quality-is-usually-the-wrong-diagnosis",children:[t(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#data-quality-is-usually-the-wrong-diagnosis",children:t(e.span,{className:"icon icon-link"})}),'"Data quality" is usually the wrong diagnosis']}),`
`,a(e.p,{children:["The figure that gets passed around is that more than 80% of AI projects fail. RAND repeated that estimate in a 2024 report, then did something more useful than repeat it. Its researchers interviewed 65 experienced data scientists and engineers about ",t(e.em,{children:"why"})," projects fail. Bad data was on the list. But the most common root cause was that people misunderstood or miscommunicated what problem the project was supposed to solve."]}),`
`,t(e.p,{children:`That matches what I see. "Data quality" is often a polite name for "we never pinned down the task." You can't tell whether your data is good enough until you know what it's for, so the data initiative launches, runs its course, and leaves the real question exactly where it was.`}),`
`,t(e.p,{children:`ChatGPT works well for individuals because the individual quietly supplies the definition of done. They steer it, notice when it's wrong, and throw away the bad output without filing a ticket. An organization needs consistent, auditable output wired into processes that predate the transformer paper. There's no one in the loop doing that judgment for free anymore, so it has to be written down in advance, and writing it down is the step most "AI transformations" skip.`}),`
`,a(e.h2,{id:"the-agent-did-exactly-what-it-was-told",children:[t(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#the-agent-did-exactly-what-it-was-told",children:t(e.span,{className:"icon icon-link"})}),"The agent did exactly what it was told"]}),`
`,t(e.p,{children:"One failure mode rarely makes the case studies: agents that work correctly and still cause a mess."}),`
`,a(e.p,{children:["Customer service agents have committed companies to deals they never meant to offer, like 50% discounts on products that weren't discountable and full refunds on non-refundable tickets. The agents weren't hallucinating. They'd been told to resolve complaints, and a 50% discount resolves a complaint quickly. Nobody had written down what a resolution was ",t(e.em,{children:"not"})," allowed to look like."]}),`
`,t(e.p,{children:'Loan decision agents have passed every technical benchmark and then failed to produce fair-lending justifications when regulators asked. The objective was "approve good loans." "Be able to explain yourself to a regulator" never made it into the spec.'}),`
`,t(e.p,{children:"Both are specification bugs. The missing half of each objective was exactly the part a human employee would have known without being told, which is why nobody thought to tell the machine."}),`
`,a(e.h2,{id:"humans-in-the-loop-wear-out",children:[t(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#humans-in-the-loop-wear-out",children:t(e.span,{className:"icon icon-link"})}),"Humans in the loop wear out"]}),`
`,t(e.p,{children:"The standard response to agents doing surprising things is a human in the loop: every action gets approved before it runs."}),`
`,t(e.p,{children:"Then the approval requests arrive by the hundreds per day. People click through without reading, and some teams end up switching on auto-approve because the interruptions are wrecking everyone's actual work. The safety layer erodes without any attacker involved, purely through the predictable behavior of people who are interrupted all day."}),`
`,t(e.p,{children:"An approval only means something if the reviewer can tell in a few seconds what they're approving. If they can't, you've built a slow rubber stamp and are paying a salary to operate it."}),`
`,a(e.h2,{id:"what-working-looks-like",children:[t(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#what-working-looks-like",children:t(e.span,{className:"icon icon-link"})}),"What working looks like"]}),`
`,t(e.p,{children:"Fraud detection keeps coming up as a genuine success, and its shape is worth copying. One agent flags anomalies, another checks compliance, a third writes up the case, and a human makes the call. The machines do the part that means chewing through enormous volumes of transactions. The person does the judgment, on a handful of well-prepared cases rather than a firehose."}),`
`,t(e.p,{children:"The task is narrow, the failure modes were known before launch, and you can tell afterward whether it worked, because the fraud was caught or it wasn't. Done was defined before anyone wrote a prompt."}),`
`,t(e.p,{children:"That pattern won't fit every use case. It does explain the back-office numbers better than any argument about which model is smartest."}),`
`,t(e.hr,{}),`
`,a(e.p,{children:["Sources: ",t(e.a,{href:"https://media-publications.bcg.com/BCG-Wheres-the-Value-in-AI.pdf",children:`BCG, "Where's the Value in AI?"`}),' (October 2024) · MIT NANDA, "The GenAI Divide: State of AI in Business 2025" · RAND, "The Root Causes of Failure for Artificial Intelligence Projects and How They Can Succeed" (2024) · ',t(e.a,{href:"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026",children:"International AI Safety Report 2026"})]})]})}function h(n={}){const{wrapper:e}=n.components||{};return e?t(e,{...n,children:t(o,{...n})}):o(n)}export{h as default,s as toc};
